  "list_media_assets": {"read_only_justification": "Reads active non-generated media library assets with optional kind and pagination; excludes conversation and task attachments by ownership.", "destructive_justification": "Does not upload files, alter metadata or add or remove media placements.", "open_world_justification": "Reads the selected business media library without fetching caller-supplied download URLs."},
